// This file is generated by AI.

// 配音队列控制器 (模块级单例)。
//
// 设计要点:
// 1. **严格串行**。GSOV 后端是单进程单 worker 且持有全局 prompt 缓存, 并发请求会互相干扰,
//    因此这里保证同一时刻最多一个在途请求。优先级完全在客户端实现。
// 2. **三个队列**。立即队列 (测试 x4)、普通队列 (生成 x32) 各自按角色分组,
//    组内连续执行, 从而避免服务端频繁重载模型; 立即队列整体优先于普通队列。
// 3. **配对**。每条任务在发起时记录参数快照与语句身份哈希, 完成后按 id 回填对应历史项。

import type {
  AudioInfo,
  CacheEntry,
  Character,
  LaunchConfig,
  ListImportReport,
  ModelCandidate,
  SayLine,
  TrimSuggestion,
  VoiceEvent,
} from '../commands/voice';
import { open as openDialog } from '@tauri-apps/plugin-dialog';
import type { CondaEnv } from '../commands/voice';
import {
  voiceCreateCharacter,
  voiceClearHistory,
  voiceDefaultLaunchConfig,
  voiceDropCache,
  voiceImportCharacter,
  voiceImportCharactersFromList,
  voiceLaunch,
  voiceListCache,
  voiceListCharacters,
  voiceListCondaEnvs,
  voiceListModels,
  voiceParseScene,
  voiceProbe,
  voiceProbeAudio,
  voiceReadHistory,
  voiceRealign,
  voiceRemoveCharacter,
  voiceRewriteLine,
  voiceSaveCharacter,
  voiceSetModel,
  voiceShutdown,
  voiceStatus,
  voiceSynthesize,
  voiceTakeLogs,
  voiceTrimSuggestion,
  voiceUpdateCharacter,
  voiceWriteHistory,
  type CharacterPatch,
} from '../commands/voice';
import { fs } from '../lib/fs';
import { useAppStore } from '../state/store';
import { estimator, formatEta } from './estimate';
import { matchScene, type CharacterMatch } from './match';
import { pickModel } from './modelPair';
import { charactersRoot, join } from './paths';
import { executionOrder, nextTask as nextQueuedTask, summarize as summarizeQueue } from './queue';
import { loadVoiceSettings, saveVoiceSettings, type VoiceSettings } from './settings';
import {
  createId,
  defaultParams,
  paramsKey,
  priorityOf,
  randomSeed,
  seedForDialogue,
  type HistoryEntry,
  type SceneVoiceState,
  type TaskPriority,
  type VoiceParams,
  type VoiceTask,
} from './types';

/** 就绪探测的上限与间隔 */
const PROBE_INTERVAL = 1500;
const PROBE_TIMEOUT = 4 * 60 * 1000;

/** 本地文件变更检查间隔 */
const DISK_CHECK_INTERVAL = 8000;

class VoiceController {
  private settings: VoiceSettings = loadVoiceSettings();
  private tasks: VoiceTask[] = [];
  private cards = new Map<string, SceneVoiceState>();
  private characters: Character[] = [];
  private referencePaths = new Map<string, string>();
  private queueRunning = false;

  private store() {
    return useAppStore.getState();
  }

  // -------- 设置 --------

  getSettings(): VoiceSettings {
    return this.settings;
  }

  updateSettings(patch: Partial<VoiceSettings>): void {
    this.settings = { ...this.settings, ...patch };
    saveVoiceSettings(this.settings);
    this.emit();
  }

  // -------- 角色库 --------

  getCharacters(): Character[] {
    return this.characters;
  }

  setCharacters(characters: Character[]): void {
    // 统一按"星标优先, 其次加入顺序"排序。
    //
    // 这里必须定序: 后端列表本身也是这个顺序, 但本地增删改后的临时数组不会自动有序,
    // 一旦顺序不稳定, 改一个角色的设置就会让它的卡片跳到别处 (看起来像卡片交换了位置)。
    this.characters = [...characters].sort(
      (a, b) => Number(b.starred) - Number(a.starred) || a.createdAt - b.createdAt || a.name.localeCompare(b.name)
    );
    this.store().setVoiceCharacters(this.characters);
    // 角色信息变化会改变匹配结果, 重算所有卡片的归属
    for (const card of this.cards.values()) this.rematch(card);
    void this.primeReferencePaths();
  }

  characterById(id: string | null): Character | null {
    if (!id) return null;
    return this.characters.find((character) => character.id === id) ?? null;
  }

  // -------- 卡片 --------

  getCard(id: string): SceneVoiceState | null {
    return this.cards.get(id) ?? null;
  }

  /** 打开 (或重新聚焦) 一个场景的配音卡: 解析对话并按内容哈希回填历史 */
  async openCard(id: string, scenePath: string, content: string, diskHash: string): Promise<SceneVoiceState> {
    const dialogues = await this.parse(content);
    const previous = this.cards.get(id);
    /*
     * 历史**跨会话存活** (见 `voice/history.rs`)。
     *
     * 以前历史只活在内存里, 而 `closeCard` 会把整张卡片从表里删掉 —— 于是"关掉配音卡
     * (或关掉选项卡) 再打开", 历史就没了: 用户明明生成/应用过, 回来却是空的。这也是
     * 重新对齐 (`realignCard`) 一直没有意义的原因 (没有东西可对齐)。
     */
    const history = previous?.history ?? (await this.loadHistory(scenePath));

    const card: SceneVoiceState = {
      id,
      scenePath,
      dialogues,
      contentVersion: 1,
      history,
      selectedHistoryId: previous?.selectedHistoryId ?? null,
      cursorLine: previous?.cursorLine ?? null,
      diskHash,
      matches: new Map(),
    };

    this.cards.set(id, card);
    this.rematch(card);
    this.refreshApplied(card);
    this.syncCard(card);
    // 从磁盘读回的历史带着上次的行号, 而它会随场景编辑漂移 -> 按内容重新对齐一次
    if (!previous) await this.realignCard(id);
    return card;
  }

  closeCard(id: string): void {
    this.cards.delete(id);
    this.syncCardStore();
  }

  /**
   * 放弃一张卡片: 撤下它未完成的任务, 再关掉卡片。
   *
   * 用于"用户确认关闭选项卡"之后的收尾 —— 卡片没了以后任务完成也没地方回填, 留着只会
   * 让服务端白白跑完一次推理。历史已经落盘, 不受影响。
   */
  abandonCard(id: string): void {
    for (const task of this.tasks) {
      if (task.cardId === id && (task.status === 'pending' || task.status === 'running')) {
        this.cancel(task.id);
      }
    }
    this.closeCard(id);
  }

  /** 关闭项目时丢弃全部场景卡与队列 (角色库属于全局, 不受影响) */
  resetProject(): void {
    this.cards.clear();
    this.tasks = [];
    this.queueRunning = false;
    const store = this.store();
    store.setSceneVoiceEditors(new Map());
    store.setVoiceCache([]);
    this.emit();
  }

  /** 场景内容变化: 重新解析并保留历史 (对齐由 `realignCard` 负责) */
  async refreshCard(id: string, content: string, contentVersion = 0): Promise<void> {
    const card = this.cards.get(id);
    if (!card) return;
    card.dialogues = await this.parse(content);
    card.contentVersion = contentVersion;
    this.rematch(card);
    this.refreshApplied(card);
    this.syncCard(card);
  }

  setCursorLine(id: string, line: number | null): void {
    const card = this.cards.get(id);
    if (!card) return;
    card.cursorLine = line;
    this.syncCard(card);
  }

  /** 依据当前角色列表重算全场景的角色归属 */
  rematch(card: SceneVoiceState): void {
    const overrides = this.store().voiceAssignments[card.scenePath] ?? {};
    const matches = matchScene(card.dialogues, this.characters, overrides);
    card.matches = matches;
  }

  matchesOf(id: string): Map<number, CharacterMatch> | null {
    return this.cards.get(id)?.matches ?? null;
  }

  /** 记录用户的手动归属 (场景级覆盖), 并对后续旁白生效 */
  assignCharacter(scenePath: string, speaker: string | null, characterId: string | null): void {
    const store = this.store();
    const map = { ...(store.voiceAssignments[scenePath] ?? {}) };
    const key = speaker ?? '';
    if (characterId) map[key] = characterId;
    else delete map[key];
    store.setVoiceAssignment(scenePath, map);
    for (const card of this.cards.values()) {
      if (card.scenePath === scenePath) {
        this.rematch(card);
        this.syncCard(card);
      }
    }
  }

  selectedHistory(id: string): HistoryEntry | null {
    const card = this.cards.get(id);
    if (!card?.selectedHistoryId) return null;
    return card.history.find((entry) => entry.id === card.selectedHistoryId) ?? null;
  }

  selectHistory(id: string, entryId: string | null): void {
    const card = this.cards.get(id);
    if (!card) return;
    card.selectedHistoryId = entryId;
    this.syncCard(card);
  }

  // -------- 参数 --------

  /**
   * 某条对话的当前配音参数 (未选中历史项时为默认值)。
   *
   * **直接接收对话本身**而不是用 `card.cursorLine` 反查: 调用方 (语句面板) 手上
   * 已经有那条对话, 再反查一次就会在"光标行号还没同步过来"的窗口里静默返回 null,
   * 于是测试/生成按钮点了没反应。少一次反查就少一个失配的机会。
   *
   * 这里也是**纯查询, 不能有副作用**: 种子必须可重复 (见 `seedForDialogue`),
   * 随机只发生在用户显式换种子的那一刻。
   */
  currentParams(id: string, line: SayLine): VoiceParams | null {
    const card = this.cards.get(id);
    if (!card) return null;

    const selected = this.selectedHistory(id);
    const defaults = this.settings.defaults;
    const match = card.matches?.get(line.line);
    const character = this.characterById(selected?.characterId ?? match?.characterId ?? null);

    const base = defaultParams(character, line.text, selected?.params.seed ?? seedForDialogue(line));
    return {
      ...base,
      language: selected?.params.language ?? defaults.language,
      temperature: selected?.params.temperature ?? defaults.temperature,
      speedFactor: selected?.params.speedFactor ?? defaults.speedFactor,
      topK: selected?.params.topK ?? defaults.topK,
      topP: selected?.params.topP ?? defaults.topP,
      repetitionPenalty: selected?.params.repetitionPenalty ?? defaults.repetitionPenalty,
      /*
       * 采样步数是"**正式生成**用几档", 因此只认生成记录: 测试记录固定 4 步, 让它
       * 回填会把面板上的步数带成 x4 —— 点一次测试, 正式生成的档位就掉下去了。
       */
      sampleSteps: (selected?.kind === 'generate' ? selected.params.sampleSteps : null) ?? defaults.generateSampleSteps,
      /*
       * 文本是参数的一部分, **可以改** (操作台上的文本框就是干这个的):
       * 选中历史项时回填它当时合成的文本, 否则默认用场景里的这一句。
       * 不要在每次取参数时无条件写回 `line.text` —— 那会把用户刚改的文本抹掉。
       */
      text: selected?.params.text ?? line.text,
    };
  }

  /** 找一个与给定参数完全一致的历史项 (用于判断"是否已是新配置") */
  findMatchingHistory(id: string, params: VoiceParams): HistoryEntry | null {
    const card = this.cards.get(id);
    if (!card) return null;
    const key = paramsKey(params);
    return card.history.find((entry) => paramsKey(entry.params) === key && entry.status !== 'failed') ?? null;
  }

  // -------- 入队 --------

  /**
   * 入队一次合成。`line` 由调用方直接给出 (见 `currentParams` 的说明)。
   *
   * `priority` 默认按任务类型给 (测试优先、生成常规), 但可以显式指定 —— 排队中的
   * 任务允许被插队或降级 (见 `setPriority`)。
   */
  enqueue(
    id: string,
    kind: 'test' | 'generate',
    line: SayLine,
    params: VoiceParams,
    priority: TaskPriority = priorityOf(kind)
  ): VoiceTask | null {
    const card = this.cards.get(id);
    if (!card) return null;

    const character = this.characterById(params.characterId);
    const reference = character?.references.find((item) => item.hash === params.referenceHash) ?? null;
    /*
     * 快照 = 用户此刻配置的这一份, **包括文本框里改过的文本**。
     *
     * 步数记录实际使用的档位 (测试固定走测试步数), 因此历史项显示的就是真跑过的;
     * 步数不参与"配置身份"的比对 (见 `paramsKey`)。
     *
     * 刻意不再用 `line.text` 覆盖文本: 那样用户在文本框里改完再点生成, 送进模型的
     * 还是场景原文 —— 界面上写着改后的文本, 音频却是原文, 属于静默丢输入。
     */
    const snapshot: VoiceParams = {
      ...params,
      sampleSteps: kind === 'test' ? this.settings.testSampleSteps : params.sampleSteps,
    };

    const task: VoiceTask = {
      id: createId('voice-task'),
      kind,
      priority,
      status: 'pending',
      cardId: id,
      scenePath: card.scenePath,
      line: line.line,
      lineHash: line.hash,
      speaker: line.speaker,
      // 展示与估算用**实际合成的文本** (用户改过就用改过的), 不是场景原文
      text: snapshot.text,
      characterId: character?.id ?? null,
      characterName: character?.name ?? '未指定角色',
      params: snapshot,
      createdAt: Date.now(),
    };

    // 历史项与任务一一对应: 任务完成后回填
    const entry: HistoryEntry = {
      id: task.id,
      kind,
      priority,
      status: 'pending',
      line: line.line,
      speaker: line.speaker,
      text: snapshot.text,
      characterId: task.characterId,
      characterName: task.characterName,
      params: snapshot,
      createdAt: task.createdAt,
      applied: false,
    };
    card.history = [entry, ...card.history];
    card.selectedHistoryId = entry.id;

    this.tasks.push(task);
    this.syncCard(card);
    this.persistHistory(card);
    this.emit();

    // 缺少必要输入时直接失败, 给出可读的提示
    if (!character) {
      this.failTask(task.id, '未选择角色');
    } else if (!reference) {
      this.failTask(task.id, '该角色没有可用的参考音频');
    } else if (!snapshot.text.trim()) {
      this.failTask(task.id, '对话内容为空');
    } else {
      void this.pump();
    }
    return task;
  }

  /**
   * 取消一个未完成的任务。
   *
   * **运行中也允许取消**: 推理本身没有中断接口, 因此取消的含义是"这一条不要了" ——
   * 结果返回后直接丢弃 (音频已进缓存, 由缓存清理回收), 队列继续往下跑。若不允许取消
   * 运行中的任务, 界面上的取消按钮在任务开始后就变成摆设。
   *
   * 取消后**从历史里删掉这一条** (任务队列里保留, 以便看清"它确实被撤下了"):
   * 用户主动撤下的东西不该继续以一条"未生成成功"的记录留在操作台上 —— 那既占位置,
   * 又让人分不清"失败"和"我取消的"。
   */
  cancel(taskId: string): void {
    const task = this.tasks.find((item) => item.id === taskId);
    if (!task || (task.status !== 'pending' && task.status !== 'running')) return;
    task.status = 'canceled';

    const card = this.cards.get(task.cardId);
    if (card) {
      card.history = card.history.filter((entry) => entry.id !== taskId);
      if (card.selectedHistoryId === taskId) card.selectedHistoryId = null;
      this.syncCard(card);
      this.persistHistory(card);
    }
    this.emit();
  }

  /** 调整**排队中**任务的优先级 (立即 / 常规); 已在跑或已结束的任务不改动 */
  setPriority(taskId: string, priority: TaskPriority): void {
    const task = this.tasks.find((item) => item.id === taskId);
    if (!task || task.status !== 'pending') return;
    task.priority = priority;
    const card = this.cards.get(task.cardId);
    const entry = card?.history.find((item) => item.id === taskId);
    if (entry) entry.priority = priority;
    if (card) {
      this.syncCard(card);
      this.persistHistory(card);
    }
    this.emit();
  }

  private failTask(taskId: string, message: string): void {
    const task = this.tasks.find((item) => item.id === taskId);
    if (!task) return;
    task.status = 'failed';
    task.error = message;
    this.updateHistory(task);
    this.emit();
  }

  // -------- 调度 --------

  /** 取下一个待执行任务: 立即队列整体优先, 队列内按角色分组连续执行 */
  private nextTask(): VoiceTask | null {
    return nextQueuedTask(this.tasks);
  }

  private async pump(): Promise<void> {
    if (this.queueRunning) return;
    this.queueRunning = true;
    try {
      for (;;) {
        const task = this.nextTask();
        if (!task) break;
        await this.runTask(task);
      }
    } finally {
      this.queueRunning = false;
      this.emit();
    }
  }

  private async runTask(task: VoiceTask): Promise<void> {
    const character = this.characterById(task.characterId);
    const reference = character?.references.find((item) => item.hash === task.params.referenceHash);
    if (!character || !reference) {
      task.status = 'failed';
      task.error = '角色或参考音频已不存在';
      this.updateHistory(task);
      return;
    }

    const refPath = await this.referencePath(character.id, reference.file);
    /*
     * 冷启动标记在**请求发出前**取走, 而不是"等到记录样本时再跳过"。
     *
     * 取走后这次推理无论成功、取消还是报错都算"冷启动已经用掉" —— 否则标记会一直挂着,
     * 白白吃掉后面一条正常任务的样本 (那条才是真正该学的东西)。
     */
    const coldStart = estimator.takeColdStart();
    task.status = 'running';
    task.startedAt = Date.now();
    this.updateHistory(task);
    this.emit();

    try {
      const result = await voiceSynthesize({
        text: task.params.text,
        textLang: task.params.language,
        refAudioPath: refPath,
        promptText: reference.text,
        promptLang: reference.language,
        sampleSteps: task.params.sampleSteps,
        temperature: task.params.temperature,
        speedFactor: task.params.speedFactor,
        topK: task.params.topK,
        topP: task.params.topP,
        repetitionPenalty: task.params.repetitionPenalty,
        seed: task.params.seed,
      });

      /*
       * 实测响应时间: 从发出请求到拿回响应。**这才是"任务耗时"** —— 响应体里给的
       * `duration` 是生成出来的音频有多长 (秒), 两者常常差一个量级 (例如响应 48 秒、
       * 音频 3.96 秒), 混在一起显示会让人以为任务只跑了 4 秒。
       */
      task.elapsed = Date.now() - (task.startedAt ?? Date.now());

      // 推理期间被取消: 结果直接丢弃 (推理无法中断, 只能不要这个结果)
      if (!this.isCanceled(task.id)) {
        task.status = 'done';
        task.audioHash = result.entry.hash;
        task.audioPath = result.entry.path;
        task.duration = result.duration;
        /*
         * 只有**真正跑完、且没被取消**的任务才进估算样本, 且冷启动那一次不算。
         *
         * 取消的任务可能只跑了一半就被丢弃, 报错的任务可能是在等超时 —— 它们的耗时没有
         * 参考价值, 收进样本只会把预估带偏 (报错前干等几分钟, 就被算成"这句话要几分钟")。
         */
        if (!coldStart) estimator.observe(task.params.sampleSteps, task.params.text.length, task.elapsed);
        this.store().upsertVoiceCache(result.entry);
      }
    } catch (error) {
      // 已取消的任务不再报错 (用户已经表明不要这一条了)
      if (!this.isCanceled(task.id)) {
        task.status = 'failed';
        task.error = error instanceof Error ? error.message : String(error);
      }
    }

    task.finishedAt = Date.now();
    this.updateHistory(task);
    this.emit();
  }

  /**
   * 任务是否已被取消。
   *
   * 必须重新查一遍而不是读 `task.status`: 等待推理的这段时间里 `cancel` 会从另一条
   * 路径改掉它, 而 TypeScript 对 `task.status` 的收窄还停留在赋值那一刻。
   */
  private isCanceled(taskId: string): boolean {
    return this.tasks.find((item) => item.id === taskId)?.status === 'canceled';
  }

  private updateHistory(task: VoiceTask): void {
    const card = this.cards.get(task.cardId);
    if (!card) return;
    const entry = card.history.find((item) => item.id === task.id);
    if (!entry) return;
    entry.status = task.status;
    entry.priority = task.priority;
    entry.startedAt = task.startedAt;
    entry.audioHash = task.audioHash;
    entry.audioPath = task.audioPath;
    entry.duration = task.duration;
    entry.elapsed = task.elapsed;
    entry.error = task.error;
    entry.finishedAt = task.finishedAt;
    this.syncCard(card);
    this.persistHistory(card);
  }

  // -------- 应用 / 移除 --------

  /**
   * 把某条对话的 `-vocal=` 改成给定值 (`null` 表示移除)。
   *
   * 数据流刻意是"**后端只改写这一行 -> 前端把它替换进文档**":
   *
   * * 编辑器里的文档才是唯一真相。直接写盘会出现"文件变了、编辑器没变", 随后磁盘变更
   *   检测把这次自写当成外部改动, 过一会儿弹出冲突对话框 (这正是之前的毛病);
   * * 是否落盘完全交给自动保存设置决定, 与普通编辑走同一条路, 不再由配音流程另立规矩;
   * * 行号只在这里用一次 (替换哪一行), 后端拿到的只是那一行的文本。
   */
  private async rewriteLine(id: string, lineNumber: number, vocal: string | null): Promise<void> {
    const card = this.cards.get(id);
    if (!card) return;
    const store = this.store();
    const doc = store.documents.find((item) => item.path === card.scenePath);
    const content = doc?.content ?? (await fs.readText(card.scenePath));

    const lines = content.split('\n');
    const current = lines[lineNumber];
    if (current === undefined) throw new Error(`第 ${lineNumber + 1} 行已不存在，场景可能已被修改`);

    lines[lineNumber] = await voiceRewriteLine(current, vocal);
    const next = lines.join('\n');

    store.updateDocument(card.scenePath, { content: next, dirty: true });
    if (store.settings.autoSave) {
      await fs.writeText(card.scenePath, next);
      store.updateDocument(card.scenePath, { content: next, dirty: false });
      /*
       * 这次写盘是**我们自己**做的, 必须同步"打开时的磁盘哈希"。
       *
       * 不同步的话, 下一次磁盘变更检测 (定时轮询 / 窗口获得焦点) 会拿磁盘上的新内容
       * 与旧哈希比对, 判定为"被外部修改", 弹出冲突对话框 —— 用户什么都没做, 却要裁决
       * 一次自己刚点出来的改动。
       */
      card.diskHash = hashText(normalizeEol(next));
    }

    await this.refreshCard(id, next);
    this.syncCard(card);
  }

  /**
   * 把已生成的音频应用到某条对话: 音频落到 `game/vocal/<角色 id>/<哈希>.wav`,
   * 并把该行的 `-vocal=` 指向它。
   */
  async apply(id: string, entryId: string): Promise<void> {
    const card = this.cards.get(id);
    if (!card) return;
    const entry = card.history.find((item) => item.id === entryId);
    if (!entry?.audioHash || !entry.audioPath) throw new Error('该记录还没有可用的音频');
    if (entry.line === null) throw new Error('该记录尚未对齐到任何语句, 请先从历史中删除');

    const project = this.store().projectPath;
    if (!project) throw new Error('尚未打开项目');

    const dialogue = card.dialogues.find((item) => item.line === entry.line);
    if (!dialogue) throw new Error('该语句已不在场景中, 请重新对齐历史');

    const character = this.characterById(entry.characterId);
    const dir = character?.id || 'narration';
    const fileName = `${entry.audioHash}.wav`;
    const targetDir = `${project.replace(/[\\/]+$/, '')}\\game\\vocal\\${dir}`;
    await fs.mkdir(targetDir);
    await fs.rename(entry.audioPath, `${targetDir}\\${fileName}`);

    await this.rewriteLine(id, entry.line, `${dir}/${fileName}`);

    entry.applied = true;
    entry.audioPath = `${targetDir}\\${fileName}`;
    this.persistHistory(card);
    this.emit();
  }

  /** 移除某条对话的配音引用 (不动历史记录) */
  async remove(id: string): Promise<void> {
    const card = this.cards.get(id);
    if (!card || card.cursorLine === null) return;
    const line = card.dialogues.find((dialogue) => dialogue.line === card.cursorLine);
    if (!line?.vocal) return;

    await this.rewriteLine(id, line.line, null);
    for (const item of card.history) {
      if (item.line === line.line) item.applied = false;
    }
    this.persistHistory(card);
    this.emit();
  }

  /** 删除一条历史记录 (缓存音频保留, 由缓存清理统一管理) */
  dropHistory(id: string, entryId: string): void {
    const card = this.cards.get(id);
    if (!card) return;
    card.history = card.history.filter((entry) => entry.id !== entryId);
    if (card.selectedHistoryId === entryId) card.selectedHistoryId = null;
    this.syncCard(card);
    this.persistHistory(card);
    this.emit();
  }

  /**
   * 删除**某一条对话**的历史记录 (可选只删测试)。
   *
   * 历史是按对话组织的 (操作台上看到的就只有当前这一句的记录), 因此批量删除也只在
   * 这一句的范围内生效 —— 否则"清空"会顺手删掉别的对话的记录, 与眼前所见不符。
   */
  dropHistoryByLine(id: string, line: number, kind?: 'test' | 'generate'): void {
    const card = this.cards.get(id);
    if (!card) return;
    const removed = card.history.filter((entry) => entry.line === line && (!kind || entry.kind === kind));
    if (removed.length === 0) return;
    const removedIds = new Set(removed.map((entry) => entry.id));
    card.history = card.history.filter((entry) => !removedIds.has(entry.id));
    if (card.selectedHistoryId && removedIds.has(card.selectedHistoryId)) card.selectedHistoryId = null;
    this.syncCard(card);
    this.persistHistory(card);
    this.emit();
  }

  /**
   * 清理"没能对齐到任何语句"的记录。
   *
   * 历史按当前对话过滤之后, 这类记录不在任何对话的列表里, 需要一个明确的入口回收,
   * 否则它们只会永远占着内存与"未完成"计数。
   */
  dropUnalignedHistory(id: string): void {
    const card = this.cards.get(id);
    if (!card) return;
    const kept = card.history.filter((entry) => entry.line !== null);
    if (kept.length === card.history.length) return;
    card.history = kept;
    if (card.selectedHistoryId && !kept.some((entry) => entry.id === card.selectedHistoryId)) {
      card.selectedHistoryId = null;
    }
    this.syncCard(card);
    this.persistHistory(card);
    this.emit();
  }

  // -------- 场景变更裁决与历史对齐 --------

  /** 记录打开卡片时的磁盘内容哈希 */
  setDiskHash(id: string, hash: string): void {
    const card = this.cards.get(id);
    if (card) card.diskHash = hash;
  }

  /**
   * 重新对齐历史到当前对话列表。
   *
   * 调用时机必须在"用户已裁决本地变更"之后, 否则裁决会再次改变行号使对齐失效。
   */
  async realignCard(id: string): Promise<void> {
    const card = this.cards.get(id);
    if (!card || card.history.length === 0) return;
    let report;
    try {
      report = await voiceRealign(
        card.history.map((entry) => ({ id: entry.id, speaker: entry.speaker, text: entry.text })),
        card.dialogues.map((dialogue) => ({
          speaker: dialogue.speaker,
          text: dialogue.text,
          index: dialogue.line,
        }))
      );
    } catch {
      // 对齐失败不该让配音卡打不开: 保留记录里的旧行号 (可能已漂移), 由用户手动重试
      return;
    }
    const byId = new Map(report.alignments.map((item) => [item.id, item]));
    for (const entry of card.history) {
      const alignment = byId.get(entry.id);
      entry.line = alignment?.index ?? null;
      entry.alignment = alignment?.kind;
      /*
       * 只同步**对话者**: 它决定下一次按内容匹配时的键。刻意不动 `text` —— 记录里的
       * 文本是"当时合成的那一句" (用户可能在操作台里改过它), 拿场景原文覆盖会让记录
       * 显示的内容与实际音频不符。
       */
      if (entry.line !== null) {
        const dialogue = card.dialogues.find((item) => item.line === entry.line);
        if (dialogue) entry.speaker = dialogue.speaker;
      }
    }
    this.refreshApplied(card);
    this.syncCard(card);
    this.persistHistory(card);
    this.emit();
  }

  alignmentSummary(id: string): { total: number; unmatched: number } | null {
    const card = this.cards.get(id);
    if (!card) return null;
    return {
      total: card.history.length,
      unmatched: card.history.filter((entry) => entry.line === null).length,
    };
  }

  // -------- GSOV 进程 --------

  private probeTimer: ReturnType<typeof setInterval> | null = null;

  /** 启动 GSOV: 拉起进程 -> 轮询探针直到就绪 */
  async startGsv(config?: LaunchConfig): Promise<void> {
    const launch = config ?? this.settings.launch;
    if (!launch) throw new Error('尚未配置 GPT-SoVITS 整合包路径');
    if (config) this.updateSettings({ launch: config });

    const store = this.store();
    /*
     * 不要清空估算样本: 机器没变, 上一次会话学到的东西仍然有效 (样本已持久化)。
     * 但要跳过**本次启动后的第一个任务** —— 它包含模型加载, 比正常推理高一个量级。
     */
    estimator.skipNextSample();
    store.setVoiceLogs([]);
    store.setVoiceStatus('starting', null);

    await voiceLaunch(launch, (event: VoiceEvent) => this.consumeEvent(event));

    const deadline = Date.now() + PROBE_TIMEOUT;
    if (this.probeTimer) clearInterval(this.probeTimer);

    await new Promise<void>((resolve, reject) => {
      this.probeTimer = setInterval(() => {
        void (async () => {
          if (Date.now() > deadline) {
            if (this.probeTimer) clearInterval(this.probeTimer);
            this.probeTimer = null;
            this.store().setVoiceStatus('error', '启动超时, 请查看日志');
            reject(new Error('GSOV 启动超时'));
            return;
          }
          try {
            const ready = await voiceProbe(launch.host, launch.port);
            if (ready) {
              if (this.probeTimer) clearInterval(this.probeTimer);
              this.probeTimer = null;
              this.store().setVoiceStatus('ready', null);
              resolve();
            }
          } catch (error) {
            if (this.probeTimer) clearInterval(this.probeTimer);
            this.probeTimer = null;
            const message = error instanceof Error ? error.message : String(error);
            this.store().setVoiceStatus('error', message);
            reject(new Error(message));
          }
        })();
      }, PROBE_INTERVAL);
    });

    /*
     * 服务就绪后**接着跑队列**。
     *
     * 队列可能因为服务停了而卡住 (例如手动停过一次服务, 或者上次关闭工作台时留下的
     * 排队任务), 那时没有新任务入队就不会有人再触发调度 —— 界面上就是"一直排队中"。
     * 启动服务是"重新具备执行条件"的时刻, 顺手推一把。
     */
    void this.pump();
  }

  /**
   * 停止 GSOV 服务。
   *
   * 状态先进入 `stopping`: 进程收尾要等一会儿 (服务端还要落盘 `tts_infer.yaml`),
   * 而关闭配音工作台时选项卡已经不在了 —— 不把这个中间状态显示出来, "服务正在关"
   * 这段时间在界面上完全不可见 (看起来像卡住)。停止完成后置为 `stopped`, 状态栏随之
   * 收起这一项。
   */
  async stopGsv(): Promise<void> {
    if (this.probeTimer) {
      clearInterval(this.probeTimer);
      this.probeTimer = null;
    }
    this.store().setVoiceStatus('stopping', null);
    try {
      await voiceShutdown();
    } finally {
      // 样本保留: 下次启动的机器与模型还是一样的 (第一个任务由 `startGsv` 标为冷启动)
      this.store().setVoiceStatus('stopped', null);
    }
  }

  /** 服务在跑就停掉 (关闭工作台时用; 没在跑则什么都不做) */
  async stopGsvIfRunning(): Promise<void> {
    const status = this.store().voiceStatus;
    if (status === 'stopped' || status === 'stopping') return;
    try {
      await this.stopGsv();
    } catch {
      // 停止失败不该阻塞关闭对话框: 状态已经落到"未启动"
      this.store().setVoiceStatus('stopped', null);
    }
  }

  /** 应用启动时同步一次状态 (进程可能已在运行) */
  async initialize(): Promise<void> {
    await this.syncStatus();
    try {
      const characters = await voiceListCharacters();
      this.setCharacters(characters);
    } catch {
      // 角色库不可用时保持空列表
    }
    await this.refreshCache();
  }

  /** 重新读取配音缓存列表 */
  async refreshCache(): Promise<void> {
    try {
      const entries = await voiceListCache();
      this.store().setVoiceCache(entries);
    } catch {
      // 缓存目录尚未建立时忽略
    }
  }

  /** 应用启动时同步一次状态 (进程可能已在运行) */
  async syncStatus(): Promise<void> {
    try {
      const status = await voiceStatus();
      this.store().setVoiceStatus(status.status, status.detail);
      const logs = await voiceTakeLogs();
      if (logs.length > 0) this.store().setVoiceLogs(this.store().voiceLogs.concat(logs));
    } catch {
      // 后端未就绪时忽略
    }
  }

  private consumeEvent(event: VoiceEvent): void {
    if (event.type === 'log') {
      this.store().appendVoiceLog(event.line);
    } else {
      this.store().setVoiceStatus(event.status, event.detail);
    }
  }

  // -------- 辅助 --------

  private async parse(content: string): Promise<SayLine[]> {
    return voiceParseScene(content);
  }

  private async referencePath(characterId: string, file: string): Promise<string> {
    return join(await charactersRoot(), characterId, file);
  }

  /** 试听等场景使用的参考音频绝对路径 */
  referencePathFor(characterId: string, file: string): string {
    return this.referencePaths.get(`${characterId}/${file}`) ?? '';
  }

  /** 预热参考音频路径 (角色列表加载后调用; 避免渲染时 await) */
  async primeReferencePaths(): Promise<void> {
    const root = await charactersRoot();
    this.referencePaths.clear();
    for (const character of this.characters) {
      for (const reference of character.references) {
        const key = `${character.id}/${reference.file}`;
        this.referencePaths.set(key, join(root, character.id, reference.file));
      }
    }
    this.emit();
  }

  /** 探测音频属性 */
  async inspectAudio(path: string): Promise<AudioInfo> {
    return voiceProbeAudio(path);
  }

  /** 裁剪建议 (波形对话框用) */
  async trimSuggestion(path: string): Promise<TrimSuggestion> {
    return voiceTrimSuggestion(path);
  }

  /** 探测整合包目录并生成默认启动配置 */
  async detect(root: string): Promise<LaunchConfig> {
    return voiceDefaultLaunchConfig(root);
  }

  /** 扫描整合包内的 v4 权重, 返回可配对的模型候选 */
  async listModels(): Promise<ModelCandidate[]> {
    const root = this.settings.launch?.root;
    if (!root) return [];
    try {
      return await voiceListModels(root);
    } catch {
      return [];
    }
  }

  /** 列出本机可用的 conda 环境 (供"从 conda 启动"选择) */
  async listCondaEnvs(): Promise<CondaEnv[]> {
    try {
      return await voiceListCondaEnvs();
    } catch {
      return [];
    }
  }

  /**
   * 显式切换服务端权重。
   *
   * 刻意只由用户主动触发: 服务端切换权重会重载模型 (SoVITS v4 需重载底模并合并 LoRA)
   * 并落盘 `tts_infer.yaml`, 属于高代价且带副作用的操作。
   * 队列通过按角色分组让同角色任务连续执行, 正常情况下无需切换。
   */
  async switchModel(gptWeights: string | null, sovitsWeights: string | null): Promise<void> {
    if (!gptWeights && !sovitsWeights) throw new Error('请先填写至少一项权重路径');
    await voiceSetModel(gptWeights, sovitsWeights);
    // 切换权重后服务端要重载底模并合并 LoRA: 下一个任务的耗时包含这部分, 不进估算样本
    estimator.skipNextSample();
  }

  /** 清理已完成/已取消的任务记录 (历史记录不受影响) */
  clearFinishedTasks(): void {
    this.tasks = this.tasks.filter((task) => task.status === 'pending' || task.status === 'running');
    this.emit();
  }

  /** 保存角色并同步到全局列表 */
  /**
   * 保存角色的**部分字段** (服务端读-改-写)。
   *
   * 这是界面上所有角色修改的入口。不要改成"发整份记录": 那会让两个相邻的修改
   * 互相覆盖 —— 勾选"参与配音"会顺手把星标、模型等字段回写成过时快照。
   */
  async updateCharacter(id: string, patch: CharacterPatch): Promise<Character> {
    const saved = await voiceUpdateCharacter(id, patch);
    this.applyCharacter(saved);
    return saved;
  }

  /**
   * 保存整份角色记录, 用于**改名** (`id` 本身变了, 无法用字段补丁表达)。
   *
   * `previousId` 是改名前的 id: id 同时是配置文件名与参考音频目录名,
   * 后端据此把音频目录一并搬走。
   */
  async persistCharacter(character: Character, previousId?: string | null): Promise<Character> {
    const saved = await voiceSaveCharacter(character, previousId);
    const rest = this.characters.filter((item) => item.id !== saved.id && item.id !== (previousId ?? saved.id));
    this.setCharacters([...rest, saved]);
    return saved;
  }

  /** 把服务端返回的角色并回本地列表 (其余角色不动) */
  private applyCharacter(saved: Character): void {
    const exists = this.characters.some((item) => item.id === saved.id);
    this.setCharacters(
      exists ? this.characters.map((item) => (item.id === saved.id ? saved : item)) : [...this.characters, saved]
    );
  }

  /** 新建角色 */
  async createCharacter(name: string, description: string): Promise<Character> {
    const created = await voiceCreateCharacter({ name, description, language: 'auto' });
    this.setCharacters([...this.characters, created]);
    return created;
  }

  async deleteCharacter(id: string): Promise<void> {
    await voiceRemoveCharacter(id);
    this.setCharacters(this.characters.filter((item) => item.id !== id));
  }

  async importCharacter(): Promise<{ character: Character; paired: number } | null> {
    const selected = await openDialog({
      multiple: false,
      filters: [{ name: '角色配置', extensions: ['zip'] }],
    });
    if (typeof selected !== 'string') return null;
    const imported = await voiceImportCharacter(selected);
    this.setCharacters([...this.characters, imported]);
    return { character: imported, paired: await this.autoAssignModels() };
  }

  /**
   * 从 GPT-SoVITS 切片产物批量导入角色与参考音频。
   *
   * 清单文件与音频目录各自独立选择, 匹配按**文件名**进行。
   */
  async importFromList(listPath: string, audioDir: string): Promise<ListImportReport & { paired: number }> {
    const report = await voiceImportCharactersFromList(listPath, audioDir);
    this.setCharacters(await voiceListCharacters());
    return { ...report, paired: await this.autoAssignModels() };
  }

  /**
   * 按角色名给"还没有模型"的角色自动配一套 GSOV 权重。
   *
   * 导入进来的角色与整合包里的权重通常同名 (训练产物就是拿这个角色训的), 让用户再逐个
   * 手选一遍纯属重复劳动。规则见 `modelPair.pickModel`: 只有名称能可信对上才配 ——
   * 配错的代价是"界面看起来已经选好了, 音色却不对", 比空着更难查。
   *
   * 返回这次配上的角色数。
   */
  async autoAssignModels(): Promise<number> {
    const models = await this.listModels();
    if (models.length === 0) return 0;
    let paired = 0;
    for (const character of [...this.characters]) {
      // 已经有任何一项权重就不动它: 那是用户自己选的 (或上次配好的)
      if (character.model?.gptWeights || character.model?.sovitsWeights) continue;
      const candidate = pickModel(character.name, models);
      if (!candidate) continue;
      try {
        await this.updateCharacter(character.id, {
          model: { gptWeights: candidate.gptWeights, sovitsWeights: candidate.sovitsWeights },
        });
        paired += 1;
      } catch {
        // 单个角色配对失败不影响导入本身
      }
    }
    return paired;
  }

  // -------- 缓存清理 --------

  async clearCache(hashes: string[]): Promise<void> {
    if (hashes.length === 0) return;
    await voiceDropCache(hashes);
    const store = this.store();
    store.setVoiceCache(store.voiceCache.filter((entry) => !hashes.includes(entry.hash)));
  }
  cacheEntry(hash: string): CacheEntry | null {
    return this.store().voiceCache.find((entry) => entry.hash === hash) ?? null;
  }

  // -------- 通知 --------

  /** 队列概览 (供 UI 展示) */
  queueSummary(): {
    pending: number;
    pendingTest: number;
    pendingGenerate: number;
    running: number;
    etaMillis: number;
    etaText: string;
    /** 立即队列对生成任务的预计延后量 */
    immediateDelayMillis: number;
  } {
    const summary = summarizeQueue(this.tasks, (tasks) => estimator.estimateAll(tasks));
    const ordered = executionOrder(this.tasks.filter((task) => task.status === 'pending'));
    const running = this.tasks.filter((task) => task.status === 'running');
    const eta = estimator.estimateAll([...running, ...ordered]);
    return {
      ...summary,
      etaMillis: eta,
      etaText: formatEta(eta),
      immediateDelayMillis: summary.delayMillis,
    };
  }

  allTasks(): VoiceTask[] {
    return this.tasks;
  }

  /** 用户在语句面板改动参数 -> 视为新配置 (旧历史项不受影响) */
  isNewConfiguration(id: string, params: VoiceParams): boolean {
    return this.findMatchingHistory(id, params) === null;
  }

  /** 在已有历史项的配置上创建一个新任务 (不修改历史项本身) */
  retryFromHistory(cardId: string, entryId: string): VoiceTask | null {
    const card = this.cards.get(cardId);
    if (!card) return null;
    const entry = card.history.find((item) => item.id === entryId);
    if (!entry || entry.line === null) return null;
    const line = card.dialogues.find((dialogue) => dialogue.line === entry.line);
    if (!line) return null;

    // 复用原记录的全部参数 (含当时合成的文本), 优先级也沿用 —— 用户把它调成"优先"
    // 是有意的, 重试不该悄悄降回去
    return this.enqueue(cardId, entry.kind, line, { ...entry.params }, entry.priority);
  }

  /** 该场景当前是否处于配音编辑模式 */
  isSceneInVoiceMode(path: string): boolean {
    return this.store().voiceModePaths.includes(path);
  }

  /** 某场景还没跑完的任务数 (排队中 + 运行中) */
  unfinishedCount(id: string): number {
    const card = this.cards.get(id);
    if (!card) return 0;
    return card.history.filter((entry) => entry.status === 'pending' || entry.status === 'running').length;
  }

  /**
   * 撤下**全部**未完成的任务。
   *
   * 关闭配音工作台时调用: 服务马上要停, 留在队列里的任务再也等不到结果, 只会变成
   * "永远排队中" (重开工作台看到它们还在, 却什么都不会发生)。已经生成出来的记录不受
   * 影响 —— 撤下的只是没产出音频的那几条。
   */
  cancelUnfinishedTasks(): void {
    for (const task of [...this.tasks]) {
      if (task.status === 'pending' || task.status === 'running') this.cancel(task.id);
    }
  }

  /**
   * 磁盘内容是否被**外部**改过。
   *
   * 判据是"磁盘既不同于打开时的基准, 也不同于编辑器里现在这一份":
   *
   * * 只比基准是不够的。基准 (`diskHash`) 只在打开卡片时记录, 而文件随时可能被**我们自己**
   *   写回去 —— 配音「应用」、手动 `Ctrl+S`、自动保存。只比基准的话, 下一次轮询就会把
   *   这些自写当成"外部修改", 弹出一个别无选择的裁决对话框。
   * * 只比编辑器内容也不够: 编辑器有未保存的改动时, 磁盘与它本来就不同, 那是脏标记而
   *   不是冲突。
   */
  async checkDiskChange(id: string): Promise<boolean> {
    const card = this.cards.get(id);
    if (!card) return false;
    try {
      const content = await fs.readTextLossy(card.scenePath);
      const diskHash = hashText(normalizeEol(content));
      if (diskHash === card.diskHash) return false;

      // 磁盘内容与编辑器里的一致 -> 是我们自己刚保存过, 顺手把基准对齐, 不打扰用户
      const doc = this.store().documents.find((item) => item.path === card.scenePath);
      if (doc && hashText(normalizeEol(doc.content)) === diskHash) {
        card.diskHash = diskHash;
        return false;
      }
      return true;
    } catch {
      return false;
    }
  }

  private syncCard(card: SceneVoiceState): void {
    this.store().setSceneVoiceEditors(new Map(this.cards));
    void card;
  }

  private syncCardStore(): void {
    this.store().setSceneVoiceEditors(new Map(this.cards));
  }

  // -------- 历史持久化 --------

  /** 写盘串行化: 保证同一份文件的多次写入按调用顺序落盘 */
  private historyWrite: Promise<void> = Promise.resolve();

  /** 读取某场景已落盘的历史 (不存在的字段一律按"没有"处理) */
  private async loadHistory(scenePath: string): Promise<HistoryEntry[]> {
    try {
      const raw = await voiceReadHistory(scenePath);
      if (!Array.isArray(raw)) return [];
      return (raw as HistoryEntry[]).filter(
        (entry) =>
          entry &&
          typeof entry.id === 'string' &&
          // 上次会话里没跑完的任务不会自己复活: 留着只会显示成永远"生成中"
          (entry.status === 'done' || entry.status === 'failed')
      );
    } catch {
      return [];
    }
  }

  /**
   * 把历史写回磁盘。
   *
   * 刻意**不 await**: 历史是旁路信息, 写盘失败 (磁盘满/权限) 不该让"应用一条配音"这种
   * 操作失败。因此这里吞掉错误 —— 但写是串行的, 后一次一定覆盖前一次, 不会交错。
   */
  private persistHistory(card: SceneVoiceState): void {
    const scenePath = card.scenePath;
    const entries = card.history;
    this.historyWrite = this.historyWrite
      .then(async () => {
        if (entries.length === 0) await voiceClearHistory(scenePath);
        else await voiceWriteHistory(scenePath, entries);
      })
      .catch(() => {
        // 忽略: 历史写不进去不影响配音本身
      });
  }

  /**
   * 重新判断每一条记录"是否已经应用到脚本"。
   *
   * `applied` 是个**派生**事实 (该行的 `-vocal=` 是否正好指向这条记录的音频), 不是可以
   * 单独存下来就算数的状态: 用户可能在普通编辑器里删掉了 `-vocal=`, 也可能回滚了文件。
   * 每次重新解析场景 / 载入历史后按脚本重算, 界面上的"已应用"才不会说谎。
   */
  private refreshApplied(card: SceneVoiceState): void {
    for (const entry of card.history) {
      if (entry.line === null || !entry.audioHash) {
        entry.applied = false;
        continue;
      }
      const dialogue = card.dialogues.find((item) => item.line === entry.line);
      const dir = this.characterById(entry.characterId)?.id || 'narration';
      const expected = `${dir}/${entry.audioHash}.wav`;
      const vocal = dialogue?.vocal?.replace(/\\/g, '/');
      entry.applied = vocal === expected;
    }
  }

  private emit(): void {
    const store = this.store();
    store.setVoiceTick();
    // 配音工作台选项卡角标: 待处理 + 运行中
    const active = this.tasks.filter((task) => task.status === 'pending' || task.status === 'running').length;
    if (store.voiceQueuePending !== active) store.setVoiceQueuePending(active);
  }
}

/** 内容哈希 (与磁盘比对用, 无需密码学强度) */
export function hashText(text: string): string {
  let hash = 0x811c9dc5;
  for (let index = 0; index < text.length; index++) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16);
}

export function normalizeEol(text: string): string {
  return text.replace(/\r\n/g, '\n');
}

/** 生成默认参数 (供 UI 直接使用) */
export function makeDefaultParams(text: string): VoiceParams {
  return defaultParams(null, text, randomSeed());
}

export const DISK_CHECK_MS = DISK_CHECK_INTERVAL;

/** 会话级单例 */
export const voiceController = new VoiceController();
